<?php require_once __DIR__.'/bootstrap.php'; $id=(int)($_GET['id']??0); if($id){$s=$pdo->prepare('SELECT a.*,GROUP_CONCAT(DISTINCT g.name SEPARATOR ", ") genres,GROUP_CONCAT(DISTINCT c.name SEPARATOR ", ") characters FROM anime a LEFT JOIN anime_genres ag ON ag.anime_id=a.id LEFT JOIN genres g ON g.id=ag.genre_id LEFT JOIN anime_characters ac ON ac.anime_id=a.id LEFT JOIN characters c ON c.id=ac.character_id WHERE a.id=? GROUP BY a.id');$s->execute([$id]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Anime not found');}$title=$a['title'].' — AniRead';include __DIR__.'/includes/header.php';?><section class="detail"><img class="poster" src="<?=e($a['poster']?:'assets/placeholder.svg')?>" alt="<?=e($a['title'])?>"><div><span class="eyebrow"><?=e($a['type'])?></span><h1><?=e($a['title'])?></h1><p class="muted"><?=e($a['synopsis'])?></p><div class="meta">★ <?=e($a['score']?:'—')?> · <?=e($a['status']?:'—')?> · <?=e($a['year']?:'—')?> · <?=e($a['episodes']?:'—')?> eps</div><p>Genres: <?=e($a['genres']?:'—')?></p><div class="actions"><a class="btn" href="<?=url('watch.php?id='.$id)?>">Watch Now</a><?php if(user()): ?><form method="post" action="watchlist.php"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="anime_id" value="<?=$id?>"><button class="btn alt">Add to Watchlist</button></form><?php endif;?></div></div></section><section class="section"><h2>Episodes</h2><div class="episode-list"><?php $es=$pdo->prepare('SELECT * FROM episodes WHERE anime_id=? ORDER BY number');$es->execute([$id]);foreach($es as $e):?><a href="<?=url('watch.php?id='.$id.'&episode='.$e['number'])?>">Episode <?=e($e['number'])?></a><?php endforeach;?></div></section><?php include __DIR__.'/includes/footer.php';exit;} $where=[];$params=[];foreach(['type','status','season','year'] as $f){if(!empty($_GET[$f])){$where[]="a.$f=?";$params[]=$_GET[$f];}}$term=trim($_GET['q']??'');if($term){$where[]='(a.title LIKE ? OR a.english_title LIKE ? OR a.japanese_title LIKE ?)';array_push($params,"%$term%","%$term%","%$term%");}$sql='SELECT a.* FROM anime a'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY '.($_GET['sort']==='rating'?'a.score DESC':'a.created_at DESC');$st=$pdo->prepare($sql);$st->execute($params);$items=$st->fetchAll();$title='Anime Catalog — AniRead';include __DIR__.'/includes/header.php';?><h1>Anime catalog</h1><form class="filters"><input class="input" name="q" placeholder="Search title" value="<?=e($term)?>"><select name="type"><option value="">All types</option><?php foreach(['TV','Movie','OVA','ONA','Special'] as $x):?><option <?=$x===($_GET['type']??'')?'selected':''?>><?=$x?></option><?php endforeach;?></select><select name="sort"><option value="recent">Recently added</option><option value="rating">Top rated</option></select><button class="btn">Filter</button></form><div class="grid"><?php foreach($items as $a)card($a);?></div><?php include __DIR__.'/includes/footer.php';
